from constraint import Problem

p = Problem()

# 定义变量，True表示骑士，False表示无赖
p.addVariable('Victoria', [True, False])
p.addVariable('Lucas', [True, False])
p.addVariable('Oliver', [True, False])
p.addVariable('Harper', [True, False])

# Victoria说："Lucas是无赖且Harper是骑士"，根据规则，Victoria == (Lucas是无赖且Harper是骑士)
def victoria_constraint(victoria, lucas, harper):
    return victoria == (not lucas and harper)
p.addConstraint(victoria_constraint, ['Victoria', 'Lucas', 'Harper'])

# Lucas说："Harper是无赖"，所以Lucas == (Harper是无赖)
def lucas_constraint(lucas, harper):
    return lucas == (not harper)
p.addConstraint(lucas_constraint, ['Lucas', 'Harper'])

# Oliver说："Lucas是无赖或者Victoria是骑士"，所以Oliver == (Lucas是无赖 or Victoria是骑士)
def oliver_constraint(oliver, lucas, victoria):
    return oliver == (not lucas or victoria)
p.addConstraint(oliver_constraint, ['Oliver', 'Lucas', 'Victoria'])

# Harper说："Harper是骑士当且仅当Oliver是无赖"，即Harper == (Harper是骑士 <-> Oliver是无赖)，等价于Harper == (harper == not oliver)
def harper_constraint(harper, oliver):
    return harper == (harper == not oliver)
p.addConstraint(harper_constraint, ['Harper', 'Oliver'])

# 求解所有可能的解
solutions = p.getSolutions()

# 打印结果
for solution in solutions:
    print({k: 'knight' if v else 'knave' for k, v in solution.items()})

