from constraint import Problem

p = Problem()

# 定义变量，True为骑士，False为无赖
p.addVariable('Daniel', [True, False])
p.addVariable('David', [True, False])
p.addVariable('Victoria', [True, False])
p.addVariable('Mason', [True, False])

# Daniel说"Mason是无赖且David是无赖"，所以Daniel == (not Mason and not David)
def daniel_constraint(daniel, mason, david):
    return daniel == (not mason and not david)
p.addConstraint(daniel_constraint, ['Daniel', 'Mason', 'David'])

# David说"Victoria是骑士且Victoria是无赖"，这句话为假，所以David == (not Victoria)
def david_constraint(david, victoria):
    return david == (not victoria)
p.addConstraint(david_constraint, ['David', 'Victoria'])

# Victoria说"Daniel是骑士"，所以Victoria == Daniel
def victoria_constraint(victoria, daniel):
    return victoria == daniel
p.addConstraint(victoria_constraint, ['Victoria', 'Daniel'])

# Mason说"Mason是骑士或Daniel是骑士"，所以Mason == (mason or daniel)
def mason_constraint(mason, daniel):
    return mason == (mason or daniel)
p.addConstraint(mason_constraint, ['Mason', 'Daniel'])

# 求解所有解
solutions = p.getSolutions()

# 输出结果
for sol in solutions:
    result = {}
    for name, is_knight in sol.items():
        result[name] = 'knight' if is_knight else 'knave'
    print(result)

from constraint import Problem

p = Problem()

# 定义变量，True表示骑士，False表示无赖
p.addVariables(['Alexander', 'Luke', 'Jackson', 'Charlotte', 'Harper'], [True, False])

# Alexander说'Harper不是骑士'，所以Alexander == (Harper为False)
def alexander_constraint(alexander, harper):
    return alexander == (not harper)
p.addConstraint(alexander_constraint, ['Alexander', 'Harper'])

# Luke说'如果Luke是骑士，那么Charlotte是骑士'，即Luke -> Charlotte，逻辑上等价于not Luke or Charlotte
def luke_constraint(luke, charlotte):
    return luke == (not luke or charlotte)
p.addConstraint(luke_constraint, ['Luke', 'Charlotte'])

# Jackson说'Luke是骑士或者Harper是无赖'，即Luke or not Harper
def jackson_constraint(jackson, luke, harper):
    return jackson == (luke or not harper)
p.addConstraint(jackson_constraint, ['Jackson', 'Luke', 'Harper'])

# Charlotte说'Charlotte是骑士'，即Charlotte == Charlotte，恒成立？不，应该是Charlotte == Charlotte为真，所以Charlotte的约束是Charlotte == Charlotte？不，不对。正确的是Charlotte的陈述是'Charlotte是骑士'，所以Charlotte的布尔值等于她的陈述为真，即Charlotte == True
def charlotte_constraint(charlotte):
    return charlotte == True
p.addConstraint(charlotte_constraint, ['Charlotte'])

# Harper说'Harper是骑士或者Jackson是骑士'，即Harper or Jackson
def harper_constraint(harper, jackson):
    return harper == (harper or jackson)
p.addConstraint(harper_constraint, ['Harper', 'Jackson'])

# 寻找所有解
solutions = p.getSolutions()

# 输出结果
for sol in solutions:
    result = {name: 'knight' if val else 'knave' for name, val in sol.items()}
    print(result)

