def jack_constr(jack, zoey, david):
    return jack == (not zoey or not david)
p.addConstraint(jack_constr, ['Jack', 'Zoey', 'David'])

# 阿米莉亚：Abigail是无赖当且仅当Zoey是无赖
def amelia_constr(amelia, abigail, zoey):
    return amelia == (abigail == zoey)
p.addConstraint(amelia_constr, ['Amelia', 'Abigail', 'Zoey'])

# 洛根：Jack是骑士当且仅当Amelia是骑士
def logan_constr(logan, jack, amelia):
    return logan == (jack == amelia)
p.addConstraint(logan_constr, ['Logan', 'Jack', 'Amelia'])

# 阿比盖尔：David是骑士且Abigail是骑士
def abigail_constr(abigail, david):
    return abigail == (david and abigail)
p.addConstraint(abigail_constr, ['Abigail', 'David'])


solutions = p.getSolutions()

for sol in solutions:
