p = Problem()

# 定义居民变量，True表示骑士，False表示无赖
residents = ['David', 'Ella', 'Matthew', 'Charlotte', 'Oliver', 'Samuel', 'Riley', 'Alexander']
for name in residents:
    p.addVariable(name, [True, False])

# David 说"Riley 不是无赖"，即 David == (Riley 是骑士)
def david_constraint(david, riley):
    return david == riley
p.addConstraint(david_constraint, ['David', 'Riley'])

# Ella 说"如果 Samuel 是无赖那么 Oliver 是骑士"，即 Ella == (not samuel or oliver)
def ella_constraint(ella, samuel, oliver):
    return ella == (not samuel or oliver)
p.addConstraint(ella_constraint, ['Ella', 'Samuel', 'Oliver'])

# Matthew 说"Samuel 是骑士或者 Riley 是无赖"，即 Matthew == (samuel or not riley)
def matthew_constraint(matthew, samuel, riley):
    return matthew == (samuel or not riley)
p.addConstraint(matthew_constraint, ['Matthew', 'Samuel', 'Riley'])

# Charlotte 说"Riley 不是骑士"，即 Charlotte == (not riley)
def charlotte_constraint(charlotte, riley):
    return charlotte == (not riley)
p.addConstraint(charlotte_constraint, ['Charlotte', 'Riley'])

# Oliver 说"David 是无赖"，即 Oliver == (not david)
def oliver_constraint(oliver, david):
    return oliver == (not david)
p.addConstraint(oliver_constraint, ['Oliver', 'David'])

# Samuel 说"Charlotte 是骑士且 Riley 是无赖"，即 Samuel == (charlotte and not riley)
def samuel_constraint(samuel, charlotte, riley):
    return samuel == (charlotte and not riley)
p.addConstraint(samuel_constraint, ['Samuel', 'Charlotte', 'Riley'])

# Riley 说"如果 Matthew 是无赖那么 Samuel 是无赖"，即 Riley == (not matthew or not samuel)
def riley_constraint(riley, matthew, samuel):
    return riley == (not matthew or not samuel)
p.addConstraint(riley_constraint, ['Riley', 'Matthew', 'Samuel'])

# Alexander 说"如果 Samuel 是无赖那么 Oliver 是无赖"，即 Alexander == (not samuel or not oliver)
def alexander_constraint(alexander, samuel, oliver):
    return alexander == (not samuel or not oliver)
p.addConstraint(alexander_constraint, ['Alexander', 'Samuel', 'Oliver'])

# 求解所有可能的解
solutions = p.getSolutions()

# 输出结果
for sol in solutions:
    result = {}
    for name, is_knight in sol.items():
        result[name] = 'knight' if is_knight else 'knave'
    print(result)

