from constraint import Problem

p = Problem()
# 定义变量，True表示骑士，False表示无赖
p.addVariable('Isabella', [True, False])
p.addVariable('Emma', [True, False])

# 处理Emma的陈述："Isabella是骑士当且仅当Isabella是无赖"，根据双条件约束，Emma == (Isabella == (not Isabella))
def emma_constraint(emma, isabella):
    return emma == (isabella == (not isabella))
p.addConstraint(emma_constraint, ['Emma', 'Isabella'])

# 处理Isabella的陈述："Isabella是骑士且Emma是骑士"，根据双条件约束，Isabella == (isabella and emma)
def isabella_constraint(isabella, emma):
    return isabella == (isabella and emma)
p.addConstraint(isabella_constraint, ['Isabella', 'Emma'])

# 寻找所有解
solutions = p.getSolutions()

# 输出结果
for sol in solutions:
    print({k:'knight' if v else 'knave' for k,v in sol.items()}}

