def avery_constraint(avery, william, isabella):
    return avery == ((not william) or (not isabella))
p.addConstraint(avery_constraint, ['Avery', 'William', 'Isabella'])

# James说："Liam不是无赖" -> James == Liam
def james_constraint(james, liam):
    return james == liam
p.addConstraint(james_constraint, ['James', 'Liam'])

# Isabella说："Liam是骑士当且仅当Liam是无赖" -> Isabella == (Liam == not Liam)
# 因为Liam == not Liam 等价于 False，所以Isabella == False
def isabella_constraint(isabella, liam):
    return isabella == (liam == not liam)
p.addConstraint(isabella_constraint, ['Isabella', 'Liam'])

# Riley说："Isabella是骑士" -> Riley == Isabella
def riley_constraint(riley, isabella):
    return riley == isabella
p.addConstraint(riley_constraint, ['Riley', 'Isabella'])

